    previousIds = [...value.previousIds];
  }

  const updatedAt = normalizeUpdatedAt(value.updatedAt);
  if (updatedAt === null) return null;
  return {
    parentBlockId,
    orderedIds,
    previousIds,
    mutationId: value.mutationId,
    items,
    updatedAt
  };
